package net.officefloor.hq.app.claim;

import java.math.BigDecimal;
import java.time.LocalDate;

/** A person's claim: an amount (two decimals; below 0.00 only for a correction), a date, a note (may be empty), its
 *  status, its number (sheet-wide digits, or <period name>-<n> / X-<n> when numbered within its period; null while a draft; a voided claim keeps the one it had) and, once settled, the due fixed
 *  at settling (null before then, or when the person's grade had no rate then: its due stays live), and
 *  who opened it (null while a draft), whether its person's last statement bound it (it counted then) and the
 *  figure it bound it to (null when not bound, or its figure was n/a then: its due stays live), and for a correction
 *  (a negative amount) the number of the SETTLED claim of the same person it corrects (null otherwise), and its
 *  due-by: the terms-th business day after the date it had when it was created, with the terms fixed then (its person's
 *  own, else their grade's in force on that date, else the sheet's), skipping Saturdays, Sundays and the sheet's
 *  holidays as they are now; it does not change when the terms or its date change later; and the date it is deferred until (null: never
 *  deferred): an OPEN claim deferred past the sheet's today is deferred (see deferredOn); and its proofs count (0 or more,
 *  raised one at a time); and the number of the claim it was split from (null when it was not split off one); and whether it is a
 *  late entry: added while its period was soft-closed (fixed when it was added); and the last sheet-today a reminder was
 *  written for it (null: never reminded). */
public record Claim(long id, String sheetId, long personId, BigDecimal amount, LocalDate date, String note,
        ClaimStatus status, String number, BigDecimal settledDue, String openedBy, boolean stated,
        BigDecimal statedDue, String corrects, LocalDate dueBy, LocalDate deferredUntil, int proofs,
        String splitFrom, boolean lateEntry, LocalDate reminded) {

    /** Whether the claim is deferred on the sheet's today: it is OPEN and deferred until a date after today (null:
     *  no today, nothing is deferred). Deferred, it counts in no total, is not overdue, cannot be settled and is
     *  left unbound by a statement; from that date on it is an OPEN claim like any other. */
    public boolean deferredOn(LocalDate today) {
        return status == ClaimStatus.OPEN && deferredUntil != null && today != null && deferredUntil.isAfter(today);
    }
}
package net.officefloor.hq.app.claim;

/** Body of a claim add or edit: who is making it, the amount as typed, the date (blank for the
 *  sheet's today), the note and, for a correction, the number of the claim it corrects (blank otherwise). */
public record ClaimRequest(String user, String amount, String date, String note, String corrects) {
}
package net.officefloor.hq.app.claim;

import java.math.BigDecimal;
import java.time.LocalDate;

/** A validated claim add or edit. The date is null when the sheet's today is to be used; corrects is the
 *  number of the claim a correction (a negative amount) corrects, null for any other claim. */
public record ClaimInput(String user, BigDecimal amount, LocalDate date, String note, String corrects) {
}
package net.officefloor.hq.app.claim;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.time.format.DateTimeParseException;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.RequestBody;

/** Bind the body and refuse it before anything is read or written: the amount is required, a
 *  number with up to two decimals, below 0.00 only for a correction, which names (by its number: a whole number, or <period name>-<n> / X-<n>) the claim it
 *  corrects, and only a correction names one; the date, when given, is a real yyyy-mm-dd date. */
public class ValidateClaim {
    public void validate(@RequestBody ClaimRequest request, Out<ClaimInput> body) throws InvalidClaimException {
        body.set(check(request));
    }

    /** The claim form's rules, shared by every way a claim is added (the paste box checks each line by them). */
    static ClaimInput check(ClaimRequest request) throws InvalidClaimException {
        if (request == null || request.user() == null || request.user().isBlank()) {
            throw new InvalidClaimException("Sign in before changing claims.");
        }
        String amount = request.amount() == null ? "" : request.amount().trim();
        if (amount.isEmpty()) {
            throw new InvalidClaimException("An amount is required.");
        }
        if (!amount.matches("-?\\d{1,12}(\\.\\d{1,2})?")) {
            throw new InvalidClaimException("The amount must be a number with up to two decimals.");
        }
        BigDecimal value = new BigDecimal(amount).setScale(2);
        String rawCorrects = request.corrects() == null ? "" : request.corrects().trim();
        String corrects = null;
        if (!rawCorrects.isEmpty()) {
            if (rawCorrects.matches("\\d{1,9}")) {
                corrects = String.valueOf(Integer.parseInt(rawCorrects));
            } else if (rawCorrects.matches(".{1,200}-\\d{1,9}")) {
                corrects = rawCorrects;
            } else {
                throw new InvalidClaimException("The claim corrected must be named by its number.");
            }
        }
        if (value.signum() < 0 && corrects == null) {
            throw new InvalidClaimException(
                    "A negative amount is a correction: name the number of the SETTLED claim it corrects.");
        }
        if (value.signum() >= 0 && corrects != null) {
            throw new InvalidClaimException("Only a correction (a negative amount) names a claim it corrects.");
        }
        String rawDate = request.date() == null ? "" : request.date().trim();
        LocalDate date = null;
        if (!rawDate.isEmpty()) {
            if (!rawDate.matches("\\d{4}-\\d{2}-\\d{2}")) {
                throw new InvalidClaimException("The date must be a date (yyyy-mm-dd).");
            }
            try {
                date = LocalDate.parse(rawDate);
            } catch (DateTimeParseException e) {
                throw new InvalidClaimException("The date must be a real date (yyyy-mm-dd).");
            }
        }
        String note = request.note() == null ? "" : request.note().trim();
        if (note.length() > 1000) {
            throw new InvalidClaimException("A note is at most 1000 characters.");
        }
        return new ClaimInput(request.user().trim(), value, date, note, corrects);
    }
}
package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.holiday.HolidayRepository;
import net.officefloor.hq.app.period.PeriodRepository;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.setting.SettingRepository;
import net.officefloor.hq.app.sheet.SheetRepository;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;

/** Store the new claim under the person; with no date given it is dated the sheet's entry date, else its today. Its terms are fixed now:
 *  the person's own terms (else the terms of the person's grade in force on its date (else the sheet's terms in force on its date)); its due-by is
 *  the terms-th business day after its date, skipping Saturdays, Sundays and the sheet's holidays. Its DRAFT line starts its status log. Due by inside a soft-closed period, it is a late entry. */
public class SaveNewClaim {
    public void save(@Val ClaimInput input, @Val Person person, SheetRepository sheets, SettingRepository settings,
            HolidayRepository holidays, PeriodRepository periods, ClaimRepository repository, ClaimLogRepository log, Out<Claim> claim) {
        claim.set(insert(input, person, sheets, settings, holidays, periods, repository, log));
    }

    /** Store one new claim as the claim form does (the paste box stores each of its lines this way). */
    static Claim insert(ClaimInput input, Person person, SheetRepository sheets, SettingRepository settings, HolidayRepository holidays,
            PeriodRepository periods, ClaimRepository repository, ClaimLogRepository log) {
        var date = input.date() != null ? input.date() : sheets.newClaimDate(person.sheetId());
        int terms = DueBy.terms(person, date, settings);
        var dueBy = holidays.dueBy(person.sheetId(), date, terms);
        Claim added = repository.insert(terms, new Claim(0, person.sheetId(), person.id(), input.amount(), date, input.note(),
                ClaimStatus.DRAFT, null, null, null, false, null, input.corrects(), dueBy, null, 0, null,
                periods.softClosedOn(person.sheetId(), dueBy) != null, null));
        log.record(added, input.user());
        return added;
    }
}
package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.sheet.SheetRepository;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;

/** Apply the edit to the loaded claim and store it; a cleared date becomes the sheet's today. */
public class SaveClaim {
    public void save(@Val ClaimInput input, @Val Claim loaded, SheetRepository sheets, ClaimRepository repository,
            Out<ClaimResponse> saved) {
        var date = input.date() != null ? input.date() : sheets.today(loaded.sheetId());
        Claim claim = new Claim(loaded.id(), loaded.sheetId(), loaded.personId(), input.amount(), date, input.note(),
                loaded.status(), loaded.number(), loaded.settledDue(), loaded.openedBy(),
                loaded.stated(), loaded.statedDue(), input.corrects(), loaded.dueBy(), loaded.deferredUntil(),
                loaded.proofs(), loaded.splitFrom(), loaded.lateEntry(), loaded.reminded());
        repository.update(claim);
        saved.set(ClaimResponse.from(claim));
    }
}
package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.person.Person;
import net.officefloor.plugin.variable.Val;

/** Record the stored add in the audit file, with the amount and date as the screen shows them. */
public class AuditClaimAdded {
    public void audit(@Val ClaimInput input, @Val Person person, @Val Claim claim, Audit audit) {
        record(input, person, claim, audit);
    }

    /** The CLAIM_ADDED line for one stored add, then LATE_ENTRY for a late entry (the paste box writes one per line it adds). */
    static void record(ClaimInput input, Person person, Claim claim, Audit audit) {
        ClaimResponse shown = ClaimResponse.from(claim);
        audit.record("CLAIM_ADDED sheet=" + claim.sheetId() + " by=" + input.user()
                + " person=" + person.name() + " amount=" + shown.amount() + " date=" + shown.date());
        if (claim.lateEntry()) {
            audit.record("LATE_ENTRY sheet=" + claim.sheetId() + " by=" + input.user()
                    + " person=" + person.name() + " amount=" + shown.amount() + " date=" + shown.date());
        }
    }
}

